/**
 * Generate the app's icons, with no image-library dependency.
 *
 * `tauri-build` requires `icons/icon.ico`, `icons/32x32.png` and
 * `icons/128x128.png` to exist. Rather than commit opaque binaries generated by
 * an external tool, this script draws everything from primitives and encodes PNG
 * (using only `node:zlib`) and ICO by hand, so `node tools/make-icons.mjs`
 * reproduces every icon byte for byte.
 *
 * One piece of artwork, in one ink per context:
 *
 * | Output | Ink | Used by |
 * |---|---|---|
 * | `32x32.png`, `128x128.png`, `256x256.png`, `icon.ico` | brand blue | the executable, Start menu, Explorer, the installer |
 * | `mark-black.png`, `mark-white.png` | one flat ink on transparency | the window/taskbar icon, chosen by the Windows system theme |
 *
 * **The mark is the app's identity everywhere.** It used to be the blue tile
 * with a chevron on it, while the bare mark was reserved for the taskbar; the
 * tile is gone, so the Start menu and Explorer now show the same whale the title
 * bar draws. The tile was the only thing that needed a second brand palette,
 * and dropping it means there is exactly one shape to keep in step.
 *
 * **Why the app icons are brand blue rather than black or white.** A file icon
 * has no theme to follow: one PNG sits in the light Explorer, the dark taskbar,
 * and a folder thumbnail, so it has to read against all of them. Black would
 * vanish on a dark taskbar, white on a light folder, and the title bar's own
 * `currentColor` trick is unavailable to a static file. The brand blue is the
 * app's accent (`--dsw-alias-brand-primary` in the light palette, and the same
 * value `theme.css` repoints the app to), so it is the one ink that is both
 * legible everywhere and already this app's colour.
 *
 * The mark itself is a cubic-Bézier outline, so rasterising it needs a real (if
 * small) path rasteriser: parse → flatten → nonzero scanline fill → box filter.
 * That is the bulk of this file.
 */

import { deflateSync } from 'node:zlib'
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const HERE = dirname(fileURLToPath(import.meta.url))
const ICON_DIR = join(HERE, '..', 'src-tauri', 'icons')
const TITLE_BAR = join(HERE, '..', 'dsh-plugin', 'title-bar', 'client.js')

/**
 * The ink the app icons are painted in.
 *
 * The light palette's `--dsw-alias-brand-primary`, i.e. the same blue
 * `theme.css` repoints the app to. Kept as one constant because the PNG, the
 * ICO, and the stylesheet are all supposed to be the same colour.
 */
const BRAND_BLUE = [65, 118, 230]

/** Ink for the two monochrome marks: near-black and near-white. */
const MARK_BLACK = [0, 0, 0]
const MARK_WHITE = [255, 255, 255]

/** Antialiasing samples per axis; 4 means 16 samples per pixel. */
const SUPERSAMPLE = 4

/**
 * Edge length of the monochrome marks.
 *
 * One size is enough because Windows is asked for the icon at its own metric
 * size (`CreateIconFromResourceEx` scales the PNG), and 256 is the largest size
 * that can ever be requested — Explorer's extra-large view.
 */
const MARK_SIZE = 256

/**
 * Fraction of the mark's canvas left empty on each side.
 *
 * A taskbar glyph that touches its own edges reads as cramped against the
 * buttons beside it, and Windows' own icons keep the same kind of gutter.
 */
const MARK_MARGIN = 0.07

/**
 * Edge length of the **app** icons written as standalone PNGs.
 *
 * A different thing from [`MARK_SIZE`]: these are the fixed sizes the shell and
 * the bundle config name, so they are written at exactly those dimensions.
 */
const APP_PNG_SIZES = [32, 128, 256]

/** The sizes packed into `icon.ico` — what a shell asks for at each view. */
const ICO_SIZES = [16, 32, 48, 64, 128, 256]

/* ── the mark: SVG path → coverage ────────────────────────────────────────── */

/**
 * Read the mark's path data out of the title bar.
 *
 * The bar draws this artwork inline and the window icon rasterises it, and the
 * two are required to be the *same* mark — so there is one copy, in the place
 * that renders it live. A missing declaration is a hard failure rather than a
 * silently different icon.
 *
 * @returns the SVG path data, in the bar's `0 0 50 50` viewBox.
 */
function readMarkPath() {
  const source = readFileSync(TITLE_BAR, 'utf8')
  const match = source.match(/var LOGO_PATH =\s*\n?\s*'([^']+)'/)
  if (match === null) {
    throw new Error(`could not find LOGO_PATH in ${TITLE_BAR}`)
  }
  return match[1]
}

/** Euclidean distance between two points. */
function distance(a, b) {
  return Math.hypot(b[0] - a[0], b[1] - a[1])
}

/**
 * Append the flattened sample points of one cubic Bézier.
 *
 * The segment count comes from the control polygon's length rather than being
 * fixed, so a long sweep gets more segments than a short one. The cap is what
 * bounds the cost: the mark has 36 curves, and each extra segment is one more
 * edge every scanline has to test.
 *
 * 256 segments per curve is far more than the *sagitta* needs — the flattened
 * chord stays within a hundredth of a unit of the true curve — and that is the
 * error that matters, because the fill is of the polygon. The gap between
 * consecutive samples is larger than one raster pixel, which is harmless: a
 * straight chord between two points on the curve is inside the shape either way.
 *
 * @param out - the point list to append to.
 * @param from - the curve's start point (already in `out`).
 * @param c1 - first control point.
 * @param c2 - second control point.
 * @param to - the curve's end point.
 */
function flattenCubic(out, from, c1, c2, to) {
  const polygon = distance(from, c1) + distance(c1, c2) + distance(c2, to)
  const steps = Math.min(256, Math.max(8, Math.ceil(polygon / 0.05)))
  for (let step = 1; step <= steps; step += 1) {
    const t = step / steps
    const u = 1 - t
    const a = u * u * u
    const b = 3 * u * u * t
    const c = 3 * u * t * t
    const d = t * t * t
    out.push([
      a * from[0] + b * c1[0] + c * c2[0] + d * to[0],
      a * from[1] + b * c1[1] + c * c2[1] + d * to[1],
    ])
  }
}

/**
 * Parse the subset of SVG path syntax the mark uses: `M`, `C`, and `Z`.
 *
 * Deliberately strict. An implicit repeat — a coordinate run with no command
 * letter, which SVG allows after most commands — would mean this parser had met
 * a path it was not written for, so it throws rather than guessing a shape.
 *
 * @param data - SVG path data.
 * @returns one `{ points, closed }` per subpath, already flattened.
 */
function parsePath(data) {
  const tokens = data.match(/[MCZ]|-?(?:\d+\.?\d*|\.\d+)/g)
  if (tokens === null) throw new Error('path is empty')

  const subpaths = []
  let current = null
  let index = 0

  /** Consume one coordinate, refusing anything that is not a number. */
  const coordinate = () => {
    const token = tokens[index]
    if (token === undefined || /[MCZ]/.test(token)) {
      throw new Error(`expected a number at token ${index}, found ${String(token)}`)
    }
    index += 1
    return Number(token)
  }

  while (index < tokens.length) {
    const command = tokens[index]
    index += 1

    if (command === 'M') {
      current = { points: [[coordinate(), coordinate()]], closed: false }
      subpaths.push(current)
    } else if (command === 'C') {
      if (current === null) throw new Error('C before any M')
      const c1 = [coordinate(), coordinate()]
      const c2 = [coordinate(), coordinate()]
      const to = [coordinate(), coordinate()]
      flattenCubic(current.points, current.points[current.points.length - 1], c1, c2, to)
    } else if (command === 'Z') {
      if (current === null) throw new Error('Z before any M')
      current.closed = true
    } else {
      throw new Error(`unsupported path command ${String(command)}`)
    }
  }
  return subpaths
}

/** The axis-aligned bounds of every point in a parsed path. */
function pathBounds(subpaths) {
  let minX = Infinity
  let minY = Infinity
  let maxX = -Infinity
  let maxY = -Infinity
  for (const subpath of subpaths) {
    for (const [x, y] of subpath.points) {
      if (x < minX) minX = x
      if (y < minY) minY = y
      if (x > maxX) maxX = x
      if (y > maxY) maxY = y
    }
  }
  return { minX, minY, maxX, maxY, width: maxX - minX, height: maxY - minY }
}

/**
 * Scale the mark into a square canvas, and emit its edges in pixel space.
 *
 * WHY THE REAL BOUNDS AND NOT THE VIEWBOX. The artwork is authored in a
 * `0 0 50 50` box but overflows it: the path reaches x = -1.52, so mapping the
 * viewBox onto the icon would clip a sliver off the whale's nose. Fitting the
 * measured bounds instead centres the mark and keeps all of it.
 *
 * The fit is "contain", so the aspect ratio is preserved. The whale is about
 * 1.5:1, which means the icon carries transparent space above and below it —
 * that is correct for a wide mark, not a bug.
 *
 * @param subpaths - the parsed, flattened path.
 * @param bounds - its bounds, from {@link pathBounds}.
 * @param size - the canvas edge, in pixels.
 * @returns closed line segments as `[x0, y0, x1, y1]`, in pixel space.
 */
function markEdges(subpaths, bounds, size) {
  const scale = (size * (1 - MARK_MARGIN * 2)) / Math.max(bounds.width, bounds.height)
  const offsetX = (size - bounds.width * scale) / 2 - bounds.minX * scale
  const offsetY = (size - bounds.height * scale) / 2 - bounds.minY * scale
  const project = ([x, y]) => [x * scale + offsetX, y * scale + offsetY]

  const edges = []
  for (const subpath of subpaths) {
    const points = subpath.points.map(project)
    for (let i = 0; i < points.length - 1; i += 1) {
      const [x0, y0] = points[i]
      const [x1, y1] = points[i + 1]
      // A cubic's flattened samples can coincide where a control point sits on
      // the curve; a zero-length edge contributes no crossing and would only
      // make the scanline sort work harder.
      if (y0 !== y1 || x0 !== x1) edges.push([x0, y0, x1, y1])
    }
    // `Z` closes the subpath. Every subpath here is closed, and a fill without
    // the closing edge leaks out of the open end.
    if (subpath.closed) {
      const [x0, y0] = points[points.length - 1]
      const [x1, y1] = points[0]
      if (y0 !== y1 || x0 !== x1) edges.push([x0, y0, x1, y1])
    }
  }
  return edges
}

/**
 * Scanline-fill an outline into a coverage map.
 *
 * Rendered at `SUPERSAMPLE` times the target size and box-filtered down, which
 * is what gives the mark clean edges at 16px — the size the taskbar actually
 * asks Windows for.
 *
 * The fill rule is **nonzero**, matching SVG's default, so this reproduces what
 * the title bar's inline `<svg>` shows. Its `winding !== 0` test is symmetric
 * under a global sign flip, so the crossing-direction convention chosen here
 * cannot invert the result.
 *
 * @param edges - closed line segments, in pixel space.
 * @param size - the canvas edge, in pixels.
 * @returns one coverage value in `[0, 1]` per pixel, row-major.
 */
function rasterize(edges, size) {
  const dim = size * SUPERSAMPLE
  const mask = new Uint8Array(dim * dim)
  const crossings = []

  for (let row = 0; row < dim; row += 1) {
    // Sample at the sub-pixel's centre. `row` is already a supersampled index,
    // so this is the same thing as mapping the row back into pixel space and
    // comparing against the edges, which are in pixel space.
    const y = (row + 0.5) / SUPERSAMPLE
    crossings.length = 0

    for (const [x0, y0, x1, y1] of edges) {
      // A horizontal edge never crosses a scanline, and this test says so
      // without a special case: both comparisons come out equal.
      if (y0 > y === y1 > y) continue
      const t = (y - y0) / (y1 - y0)
      crossings.push([x0 + t * (x1 - x0), y1 > y0 ? 1 : -1])
    }
    if (crossings.length < 2) continue

    crossings.sort((a, b) => a[0] - b[0])

    const base = row * dim
    let winding = 0
    for (let i = 0; i < crossings.length - 1; i += 1) {
      winding += crossings[i][1]
      if (winding === 0) continue
      // A crossing is in pixel space; the mask is `SUPERSAMPLE` times wider, so
      // the span has to be scaled up before it is used as a column range. This
      // is the one place the two spaces meet, and forgetting the factor renders
      // a horizontally squashed mark rather than an obviously broken one.
      const from = Math.max(0, Math.ceil(crossings[i][0] * SUPERSAMPLE - 0.5))
      const to = Math.min(dim - 1, Math.floor(crossings[i + 1][0] * SUPERSAMPLE - 0.5))
      for (let x = from; x <= to; x += 1) mask[base + x] = 1
    }
  }

  const samples = SUPERSAMPLE * SUPERSAMPLE
  const coverage = new Float32Array(size * size)
  for (let py = 0; py < size; py += 1) {
    for (let px = 0; px < size; px += 1) {
      let hits = 0
      for (let sy = 0; sy < SUPERSAMPLE; sy += 1) {
        const base = (py * SUPERSAMPLE + sy) * dim + px * SUPERSAMPLE
        for (let sx = 0; sx < SUPERSAMPLE; sx += 1) hits += mask[base + sx]
      }
      coverage[py * size + px] = hits / samples
    }
  }
  return coverage
}

/**
 * Render the bare mark: one flat ink, antialiased, on transparency.
 *
 * @param size - the canvas edge, in pixels.
 * @param ink - the `[r, g, b]` to paint the mark with.
 * @returns raw RGBA bytes, row-major.
 */
function renderMark(size, ink) {
  const subpaths = parsePath(readMarkPath())
  const edges = markEdges(subpaths, pathBounds(subpaths), size)
  const coverage = rasterize(edges, size)
  const pixels = Buffer.alloc(size * size * 4)

  for (let i = 0; i < coverage.length; i += 1) {
    const offset = i * 4
    pixels[offset] = ink[0]
    pixels[offset + 1] = ink[1]
    pixels[offset + 2] = ink[2]
    pixels[offset + 3] = Math.round(coverage[i] * 255)
  }
  return pixels
}

/* ── encoders ─────────────────────────────────────────────────────────────── */

/** Precomputed CRC-32 table, per the PNG specification. */
const CRC_TABLE = (() => {
  const table = new Uint32Array(256)
  for (let n = 0; n < 256; n += 1) {
    let c = n
    for (let k = 0; k < 8; k += 1) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1
    table[n] = c >>> 0
  }
  return table
})()

function crc32(buffer) {
  let c = 0xffffffff
  for (const byte of buffer) c = CRC_TABLE[(c ^ byte) & 0xff] ^ (c >>> 8)
  return (c ^ 0xffffffff) >>> 0
}

/** Encode one PNG chunk: length, type, payload, CRC. */
function chunk(type, payload) {
  const length = Buffer.alloc(4)
  length.writeUInt32BE(payload.length, 0)
  const typeAndPayload = Buffer.concat([Buffer.from(type, 'latin1'), payload])
  const crc = Buffer.alloc(4)
  crc.writeUInt32BE(crc32(typeAndPayload), 0)
  return Buffer.concat([length, typeAndPayload, crc])
}

/**
 * Encode raw RGBA pixels as a PNG.
 *
 * @param size - edge length in pixels.
 * @param pixels - raw RGBA bytes, row-major.
 * @returns the complete PNG file bytes.
 */
function encodePng(size, pixels) {
  const signature = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])

  const ihdr = Buffer.alloc(13)
  ihdr.writeUInt32BE(size, 0)
  ihdr.writeUInt32BE(size, 4)
  ihdr[8] = 8 // bit depth
  ihdr[9] = 6 // color type: RGBA
  ihdr[10] = 0 // compression: deflate
  ihdr[11] = 0 // filter: adaptive
  ihdr[12] = 0 // interlace: none

  // Each scanline is prefixed with its filter byte; filter 0 (None) keeps the
  // encoder simple and still compresses well for flat artwork.
  const stride = size * 4
  const raw = Buffer.alloc((stride + 1) * size)
  for (let y = 0; y < size; y += 1) {
    raw[y * (stride + 1)] = 0
    pixels.copy(raw, y * (stride + 1) + 1, y * stride, (y + 1) * stride)
  }

  return Buffer.concat([
    signature,
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0)),
  ])
}

/**
 * Encode an ICO containing PNG-compressed entries.
 *
 * Windows Vista and later read PNG payloads directly from an ICO, which avoids
 * re-implementing the legacy BMP-with-AND-mask encoding.
 *
 * @param entries - `{ size, png }` pairs; entries larger than 256 are skipped.
 * @returns the complete ICO file bytes.
 */
function encodeIco(entries) {
  const header = Buffer.alloc(6)
  header.writeUInt16LE(0, 0) // reserved
  header.writeUInt16LE(1, 2) // type: icon
  header.writeUInt16LE(entries.length, 4)

  let offset = header.length + entries.length * 16
  const directory = []
  for (const { size, png } of entries) {
    const entry = Buffer.alloc(16)
    entry[0] = size >= 256 ? 0 : size // 0 means 256
    entry[1] = size >= 256 ? 0 : size
    entry[2] = 0 // palette size
    entry[3] = 0 // reserved
    entry.writeUInt16LE(1, 4) // color planes
    entry.writeUInt16LE(32, 6) // bits per pixel
    entry.writeUInt32LE(png.length, 8) // payload size
    entry.writeUInt32LE(offset, 12) // payload offset
    directory.push(entry)
    offset += png.length
  }

  return Buffer.concat([header, ...directory, ...entries.map((entry) => entry.png)])
}

/* ── entry point ──────────────────────────────────────────────────────────── */

/**
 * Write every icon.
 *
 * Exported, and guarded below, so a check script can import the drawing
 * primitives without this running as a side effect of the import.
 */
export function main() {
  mkdirSync(ICON_DIR, { recursive: true })

  // The app's own icons: the mark in brand blue, which is what the Start menu,
  // Explorer, the taskbar's pinned shortcut, and the installer show.
  for (const size of APP_PNG_SIZES) {
    const png = encodePng(size, renderMark(size, BRAND_BLUE))
    writeFileSync(join(ICON_DIR, `${size}x${size}.png`), png)
    console.log(`wrote ${size}x${size}.png (${png.length} bytes)`)
  }

  // The ICO carries the small sizes a shell needs plus a large size for
  // Explorer's extra-large views, all rendered at their own resolution rather
  // than scaled from one bitmap. Below ~32px the whale's tail thins out, so the
  // 16px entry is the one to look at if the icon is ever redrawn.
  const icoEntries = ICO_SIZES.map((size) => ({
    size,
    png: encodePng(size, renderMark(size, BRAND_BLUE)),
  }))
  const ico = encodeIco(icoEntries)
  writeFileSync(join(ICON_DIR, 'icon.ico'), ico)
  console.log(`wrote icon.ico (${ico.length} bytes, ${icoEntries.length} sizes)`)

  // The same mark in one flat ink each, for the window/taskbar icon, which
  // follows the *Windows* theme rather than the app's. One size each: Windows is
  // handed the pixel size it asks for and scales from this source, and 256 is
  // the largest it can want.
  for (const [name, ink] of [
    ['mark-black.png', MARK_BLACK],
    ['mark-white.png', MARK_WHITE],
  ]) {
    const png = encodePng(MARK_SIZE, renderMark(MARK_SIZE, ink))
    writeFileSync(join(ICON_DIR, name), png)
    console.log(`wrote ${name} (${png.length} bytes, ${MARK_SIZE}x${MARK_SIZE})`)
  }
}

// Only draw when run as a program. Importing this file (a test, or a check
// script) must not rewrite the icons as a side effect.
if (process.argv[1] !== undefined && fileURLToPath(import.meta.url) === process.argv[1]) {
  main()
}

export {
  BRAND_BLUE,
  ICON_DIR,
  MARK_BLACK,
  MARK_SIZE,
  MARK_WHITE,
  TITLE_BAR,
  encodeIco,
  encodePng,
  markEdges,
  parsePath,
  pathBounds,
  rasterize,
  readMarkPath,
  renderMark,
}
